const current_time = {
  format: "中州历-xx月-xx日",
  example: "中州历-三月-十五日",
  usage: "记录事件时间，推动剧情"
};

function numberToChinese(num) {
  const chineseNums = ['零', '一', '二', '三', '四', '五', '六', '七', '八', '九', '十'];
  if (num <= 10) return chineseNums[num];
  if (num < 20) return '十' + (num > 10 ? chineseNums[num - 10] : '');
  return chineseNums[Math.floor(num / 10)] + '十' + (num % 10 ? chineseNums[num % 10] : '');
}

let story_time = "中州历-三月-十七日";

function advanceTime(days) {
  let [year, month, day] = story_time.split('-');
  month = parseInt(month.replace(/\D/g,''));
  day = parseInt(day.replace(/\D/g,''));
  day += days;
  month += Math.floor((day - 1) / 30);
  day = (day - 1) % 30 + 1;
  month = (month - 1) % 12 + 1;
  story_time = `中州历-${numberToChinese(month)}月-${numberToChinese(day)}日`;
}

const location = {
  description: "角色当前所在地点",
  format: "区域-具体位置",
  usage: "反映角色位置,推动剧情发展"
};

function updateLocation(character, newLocation) {
  character.currentLocation = newLocation;
  console.log(`${character.name}已移动到: ${newLocation}`);
}

<movable_location>{{user}}所在地点周围三个可以探索的地点名称</movable_location>

const character_name = {
  description: "{{user}}",
}

const realm = {
  description: "角色当前的修为境界",
  format: "xx期|第x层",
  usage: "反映角色修炼进度,推动剧情发展",
  levels: [
    { name: "练气期", layers: 9, coreSize: "如石榴果粒般大小" },
    { name: "筑基期", layers: 3, coreSize: "如葡萄般大小" },
    { name: "金丹期", layers: 3, coreSize: "如樱桃般大小" },
    { name: "元婴期", layers: 3, coreSize: "如李子般大小" },
    { name: "大乘期", layers: 3, coreSize: "如猕猴桃般大小" },
    { name: "渡劫期", layers: 3, coreSize: "如柿子般大小" },
    { name: "散仙期", layers: 3, coreSize: "如橙子般大小" },
    { name: "仙君期", layers: 3, coreSize: "如芒果般大小" },
    { name: "仙尊期", layers: 3, coreSize: "如蟠桃般大小" },
    { name: "仙帝", layers: "无", coreSize: "幻化无形" }
  ]
};

function updateRealm(character) {
  let currentRealmIndex = realm.levels.findIndex(level => level.name === character.realm.split('|')[0]);
  let currentLayer = parseInt(character.realm.split('|')[1].replace(/\D/g,''));

  currentLayer++;
  if (currentLayer > realm.levels[currentRealmIndex].layers) {
    currentRealmIndex++;
    currentLayer = 1;
  }

  if (currentRealmIndex < realm.levels.length - 1) {
    character.realm = `${realm.levels[currentRealmIndex].name}|第${currentLayer}层`;
    console.log(`恭喜！${character.name}突破到了${character.realm}`);
  } else if (currentRealmIndex === realm.levels.length - 1) {
    character.realm = `${realm.levels[currentRealmIndex].name}|无`;
    console.log(`恭喜！${character.name}成功飞升,达到了${character.realm}境界！`);
  } else {
    console.log(`${character.name}已经达到了修炼的巅峰！`);
  }
}

function generateBreakthroughPercentage() {
  // 生成0到100之间的随机数
  let percentage = Math.floor(Math.random() * 101);

  // 如果百分比为100，重新生成一个99以下的数
  while (percentage === 100) {
    percentage = Math.floor(Math.random() * 100);
  }

  return percentage;
}

const sect = {
  description: "角色隶属的门派",
  format: "门派名称或'散修'",
  usage: "反映角色背景,影响剧情发展"
};

function updateSect(character, newSect) {
  if (newSect) {
    character.sect = newSect;
    console.log(`${character.name}加入了${newSect}`);
  } else {
    character.sect = "散修";
    console.log(`${character.name}成为了散修`);
  }
}

const core = {
  type: {
    description: "核心的类型",
    possibleValues: ["阴核", "阳核"],
    determiner: "根据角色的性别决定"
  },
  size: {
    description: "核心的大小",
    range: [
      "如石榴果粒般大小",
      "如葡萄般大小",
      "如樱桃般大小",
      "如李子般大小",
      "如猕猴桃般大小",
      "如柿子般大小",
      "如橙子般大小",
      "如芒果般大小",
      "如蟠桃般大小",
      "幻化无形"
    ],
    determiner: "根据修炼境界决定"
  },
  appearance: {
    description: "核心的外观",
    components: ["颜色", "气息", "质地"],
    influencers: ["性别", "功法", "灵药"]
  }
};

function updateCore(character) {
  // 更新核心类型
  character.core_type = character.gender === '男' ? '阳核' : '阴核';

  // 更新核心大小
  const realmIndex = realm.levels.findIndex(level => level.name === character.realm.split('|')[0]);
  character.core_size = realm.levels[realmIndex].coreSize;

  // 更新核心外观
  let coreColors = [], coreAuras = [], coreTextures = [];

  // 初始核心特征
  if (character.gender === '男') {
    coreColors.push('金色');
    coreAuras.push('阳刚之气');
    coreTextures.push('坚硬');
  } else {
    coreColors.push('银色');
    coreAuras.push('阴柔之气');
    coreTextures.push('柔软');
  }

  // 根据功法和灵药更新核心特征
  character.skills.forEach(skill => {
    if (skill.includes('土')) {
      coreColors.push('褐色');
      coreAuras.push('厚重之气');
      coreTextures.push('沉稳');
    } else if (skill.includes('风')) {
      coreColors.push('青色');
      coreAuras.push('轻灵之气');
      coreTextures.push('飘逸');
    }
    // 可以继续添加其他属性的判断
  });

  character.inventory.forEach(item => {
    if (item.includes('魔魂丹')) {
      coreColors.push('紫色');
      coreAuras.push('黑烟');
    } else if (item.includes('玄冰草')) {
      coreColors.push('白色');
      coreAuras.push('寒气');
    }
    // 可以继续添加其他灵药的影响
  });

  // 生成核心外观描述
  if (character.realm === '仙帝|无') {
    character.core_appearance = `核心已幻化无形,超脱物质界限,蕴含无尽玄机。`;
  } else {
    character.core_appearance = `核心呈${coreColors.join('、')}等色彩交织，`;
    if (coreColors.length > 1) {
      character.core_appearance += '呈现出多彩的光泽，';
    }
    character.core_appearance += `散发出${coreAuras.join('、')}，`;
    character.core_appearance += `质地${coreTextures.join('、')}。`;
  }
}

const skills = {
  description: "角色学会的功法",
  format: "序号.功法名称[学习进度][功能简介]",
  progressLevels: ["初学", "小成", "大成", "化境"],
  usage: "展示角色的修炼成果和战斗能力"
};

function updateSkills(character) {
  character.skills = character.skills.map((skill, index) => {
    const progress = getSkillProgress(skill);
    const description = getSkillDescription(skill);
    return `${index + 1}.${skill.name}[${progress}][${description}]`;
  }).join('\n');
}

function getSkillProgress(skill) {
  const progressIndex = Math.floor(skill.experience / 25);
  return skills.progressLevels[Math.min(progressIndex, 3)];
}

function getSkillDescription(skill) {
  return skill.shortDescription || "暂无描述";
}

function generateSpiritStones() {
  // 生成1到10000之间的随机数
  let baseAmount = Math.floor(Math.random() * 10000) + 1;

  // 有10%的概率获得额外的灵石（最多再加10000）
  if (Math.random() < 0.1) {
    baseAmount += Math.floor(Math.random() * 10000) + 1;
  }

  // 返回格式化后的字符串
  return `灵石[${baseAmount}][中州大陆通用货币]`;
}

const inventory = {
  description: "角色当前拥有的物品",
  format: "序号.物品名称[数量][简短描述]",
  usage: "展示角色的资源和装备情况"
};

function updateInventory(character) {
  character.inventory = character.items.map((item, index) => {
    return `${index + 1}.${item.name}[${item.quantity}][${item.description}]`;
  }).join('\n');
}

const relationships = {
  friends: {
    description: "与角色关系较好的人",
    format: "序号.角色名[好感度](变化值)",
    range: "1到100的正整数",
    emptyMessage: "无"
  },
  enemies: {
    description: "角色敌视或敌视角色的人",
    format: "序号.角色名[好感度](变化值)",
    range: "-100到-1的负整数",
    emptyMessage: "无"
  },
  spouse: {
    description: "角色当前拥有的道侣",
    format: "序号.角色名[爱情度](变化值)",
    range: "1到100的正整数",
    emptyMessage: "无"
  }
};

function updateRelationships(character) {
  if (character.friendList.length === 0) {
    character.friends = relationships.friends.emptyMessage;
  } else {
    character.friends = character.friendList.map((friend, index) => {
      const change = friend.recentChange || 0;
      return `${index + 1}.${friend.name}[${friend.favorability}](${change >= 0 ? '+' : ''}${change})`;
    }).join('\n');
  }

  if (character.enemyList.length === 0) {
    character.enemies = relationships.enemies.emptyMessage;
  } else {
    character.enemies = character.enemyList.map((enemy, index) => {
      const change = enemy.recentChange || 0;
      return `${index + 1}.${enemy.name}[${enemy.favorability}](${change >= 0 ? '+' : ''}${change})`;
    }).join('\n');
  }

  if (character.spouseList.length === 0) {
    character.spouse = relationships.spouse.emptyMessage;
  } else {
    character.spouse = character.spouseList.map((spouse, index) => {
      const change = spouse.recentChange || 0;
      return `${index + 1}.${spouse.name}[${spouse.loyalty}](${change >= 0 ? '+' : ''}${change})`;
    }).join('\n');
  }
}

const tasks = {
  description: "角色当前的目标",
  format: "序号.任务名[进度百分比](变化值%)状态",
  usage: "展示角色的任务进度,推动剧情发展"
};

function updateTasks(character) {
  character.tasks = character.taskList.map((task, index) => {
    let taskString = `${index + 1}.${task.name}[${task.progress}%]`;
    if (task.recentChange) {
      const changeSign = task.recentChange > 0 ? '+' : '';
      taskString += `(${changeSign}${task.recentChange}%)`;
    }
    if (task.progress === 100) {
      taskString += "完成！";
    } else if (task.isNew) {
      taskString += "new！";
    }
    return taskString;
  }).join('\n');

  character.taskList = character.taskList.filter(task => task.progress < 100);
}function addNewTask(character, taskName) {
  character.taskList.push({
    name: taskName,
    progress: 0,
    isNew: true,
    recentChange: 0
  });
  updateTasks(character);
}

function updateTaskProgress(character, taskName, newProgress) {
  const task = character.taskList.find(t => t.name === taskName);
  if (task) {
    const oldProgress = task.progress;
    task.progress = Math.min(Math.max(newProgress, 0), 100);
    task.recentChange = task.progress - oldProgress;
    task.isNew = false;
    updateTasks(character);
  }
}

const chronicle = {
  description: "中州风云录",
  updateFrequency: "每天一次",
  displayCount: 5,
  nsfwCount: 2,
  sources: ["修炼界传讯", "坊间流言", "天机感应", "秘密情报"],
  usage: "记录和展示中州大陆上发生的重要事件和变化"
};

function generateChronicle() {
  let events = [];
  let nsfwEvents = 0;

  while (events.length < 5) {
    let newEvent = generateEvent();
    if (!events.includes(newEvent)) {
      if (newEvent.isNsfw && nsfwEvents < 2) {
        events.push(newEvent);
        nsfwEvents++;
      } else if (!newEvent.isNsfw) {
        events.push(newEvent);
      }
    }
  }

  return events.map(event => `[${event.source}] ${event.content}`).join('\n');
}

function generateEvent() {
  let sources = ["修炼界传讯", "坊间流言", "天机感应", "秘密情报"];
  let source = sources[Math.floor(Math.random() * sources.length)];
  let isNsfw = Math.random() < 0.4;

  let content = generateRandomContent(isNsfw);

  return { source, content, isNsfw };
}

function generateRandomContent(isNsfw) {
  // 这里应该实现一个复杂的随机事件生成系统
  // 可以使用多个数组组合不同的事件元素，如地点、人物、行为等
  // 以下仅为示例框架
  let eventTypes = isNsfw ? getNsfwEventTypes() : getNormalEventTypes();
  let eventType = eventTypes[Math.floor(Math.random() * eventTypes.length)];

  let locations = getRandomLocations();
  let characters = getRandomCharacters();
  let actions = getRandomActions(isNsfw);

  return `${characters[0]}在${locations[0]}${actions[0]}，引发了${eventType}。`;
}

function getNormalEventTypes() {
  return ["修炼界震动", "门派纷争", "奇遇机缘", "天地异象", "秘境出世", "法宝出世", "功法出世"];
}

function getNsfwEventTypes() {
  return ["双修丑闻", "采补案件", "淫秽仪式", "人体炼丹", "欲望失控", "性奴拍卖"];
}

function getRandomLocations() {
  // 返回随机地点数组
}

function getRandomCharacters() {
  // 返回随机角色数组
}

function getRandomActions(isNsfw) {
