    } else if (task.isNew) {
      taskString += "new！";
    }
    return taskString;
  }).join('\n');

  character.taskList = character.taskList.filter(task => task.progress < 100);
}function addNewTask(character, taskName) {
  character.taskList.push({
    name: taskName,
    progress: 0,
    isNew: true,
    recentChange: 0
  });
  updateTasks(character);
}

function updateTaskProgress(character, taskName, newProgress) {
  const task = character.taskList.find(t => t.name === taskName);
  if (task) {
    const oldProgress = task.progress;
    task.progress = Math.min(Math.max(newProgress, 0), 100);
    task.recentChange = task.progress - oldProgress;
    task.isNew = false;
    updateTasks(character);
  }
}

