const current_time = {
  format: "中州历-xx月-xx日",
  example: "中州历-三月-十五日",
  usage: "记录事件时间，推动剧情"
};

function numberToChinese(num) {
  const chineseNums = ['零', '一', '二', '三', '四', '五', '六', '七', '八', '九', '十'];
  if (num <= 10) return chineseNums[num];
  if (num < 20) return '十' + (num > 10 ? chineseNums[num - 10] : '');
  return chineseNums[Math.floor(num / 10)] + '十' + (num % 10 ? chineseNums[num % 10] : '');
}

let story_time = "中州历-三月-十七日";

function advanceTime(days) {
  let [year, month, day] = story_time.split('-');
  month = parseInt(month.replace(/\D/g,''));
  day = parseInt(day.replace(/\D/g,''));
  day += days;
  month += Math.floor((day - 1) / 30);
  day = (day - 1) % 30 + 1;
  month = (month - 1) % 12 + 1;
  story_time = `中州历-${numberToChinese(month)}月-${numberToChinese(day)}日`;
}

