  levels: [
    { name: "练气期", layers: 9, coreSize: "如石榴果粒般大小" },
    { name: "筑基期", layers: 3, coreSize: "如葡萄般大小" },
    { name: "金丹期", layers: 3, coreSize: "如樱桃般大小" },
    { name: "元婴期", layers: 3, coreSize: "如李子般大小" },
    { name: "大乘期", layers: 3, coreSize: "如猕猴桃般大小" },
    { name: "渡劫期", layers: 3, coreSize: "如柿子般大小" },
    { name: "散仙期", layers: 3, coreSize: "如橙子般大小" },
    { name: "仙君期", layers: 3, coreSize: "如芒果般大小" },
    { name: "仙尊期", layers: 3, coreSize: "如蟠桃般大小" },
    { name: "仙帝", layers: "无", coreSize: "幻化无形" }
  ]
};

function updateRealm(character) {
  let currentRealmIndex = realm.levels.findIndex(level => level.name === character.realm.split('|')[0]);
  let currentLayer = parseInt(character.realm.split('|')[1].replace(/\D/g,''));

  currentLayer++;
  if (currentLayer > realm.levels[currentRealmIndex].layers) {
    currentRealmIndex++;
    currentLayer = 1;
  }

  if (currentRealmIndex < realm.levels.length - 1) {
    character.realm = `${realm.levels[currentRealmIndex].name}|第${currentLayer}层`;
    console.log(`恭喜！${character.name}突破到了${character.realm}`);
  } else if (currentRealmIndex === realm.levels.length - 1) {
    character.realm = `${realm.levels[currentRealmIndex].name}|无`;
    console.log(`恭喜！${character.name}成功飞升,达到了${character.realm}境界！`);
  } else {
    console.log(`${character.name}已经达到了修炼的巅峰！`);
  }
}

function generateBreakthroughPercentage() {
  // 生成0到100之间的随机数
  let percentage = Math.floor(Math.random() * 101);

  // 如果百分比为100，重新生成一个99以下的数
  while (percentage === 100) {
    percentage = Math.floor(Math.random() * 100);
  }

  return percentage;
}

