function generateChronicle() {
  let events = [];
  let nsfwEvents = 0;

  while (events.length < 5) {
    let newEvent = generateEvent();
    if (!events.includes(newEvent)) {
      if (newEvent.isNsfw && nsfwEvents < 2) {
        events.push(newEvent);
        nsfwEvents++;
      } else if (!newEvent.isNsfw) {
        events.push(newEvent);
      }
    }
  }

  return events.map(event => `[${event.source}] ${event.content}`).join('\n');
}

